mapper.select:
SELECT * FROM (SELECT s.*, IFNULL((SELECT MIN(money) FROM shops_room r WHERE r.shop_id = s.shop_id AND r.is_enable = 1), 0) AS minMoney, (SELECT COUNT(0) FROM shops_room r WHERE r.shop_id = s.shop_id AND r.is_enable = 1) AS roomCount, (SELECT COUNT(0) FROM orders o WHERE o.shop_id = s.shop_id AND o.order_status = 3) AS orderCount
,(st_distance(point(s.lng, s.lat), point(#{shops.lng}, #{shops.lat})) * 111195) AS distance
,NULL AS distance
FROM shops s WHERE s.is_enable = 1 and s.audit_status = 1
and s.shop_name like concat('%', #{shops.shopName}, '%')
and s.city like concat('%', #{shops.city}, '%')
and s.is_recommend = #{shops.isRecommend}
and s.shop_type = #{shops.shopType}
and exists ( select 1 from shops_room r left join shops_room_type rt on r.room_type_id = rt.id where r.shop_id = s.shop_id and r.is_enable = 1 and ( r.room_type like concat('%', '钟点', '%') or rt.type_name like concat('%', '钟点', '%') ) )
and s.create_time >= #{startTime}
and s.create_time <= #{endTime}
) t1 WHERE t1.roomCount > 0
and t1.minMoney >= #{shops.minPrice}
and t1.minMoney <= #{shops.maxPrice}
ORDER BY t1.distance IS NULL, t1.distance ASC, t1.is_recommend DESC, t1.create_time DESC
ORDER BY t1.orderCount DESC, t1.is_recommend DESC, t1.create_time DESC
ORDER BY t1.score DESC, t1.create_time DESC
ORDER BY t1.score ASC, t1.create_time DESC
ORDER BY t1.is_recommend DESC, t1.create_time DESC

select s.*,u.user_name as userName from shops s left join tb_user u on s.user_id = u.user_id
and s.shop_name like concat('%', #{shops.shopName}, '%')
and s.city like concat('%', #{shops.city}, '%')
and s.is_recommend = #{shops.isRecommend}
and s.audit_status = #{shops.auditStatus}
and s.shop_type = #{shops.shopType}
and u.user_name like concat ('%',#{shops.userName},'%')
and s.shop_phone like concat ('%',#{shops.shopPhone},'%')
order by s.create_time desc
